<?php
if(!defined('ABSPATH'))exit;
add_action('admin_menu',function(){add_menu_page('ServiceFlow','ServiceFlow','manage_options','serviceflow','sf_admin','dashicons-car',26);});
function sf_admin(){if(!current_user_can('manage_options'))return;global $wpdb;$t=sf_tables();$status=isset($_GET['sf_status'])?sanitize_key($_GET['sf_status']):'';$source=isset($_GET['sf_source'])?sanitize_key($_GET['sf_source']):'';$where=' WHERE 1=1';$args=[];if($status){$where.=' AND status=%s';$args[]=$status;}if($source){$where.=' AND source=%s';$args[]=$source;}$sql="SELECT * FROM {$t['leads']}".$where.' ORDER BY id DESC LIMIT 100';$rows=$wpdb->get_results($args?$wpdb->prepare($sql,$args):$sql,ARRAY_A);echo '<div class="wrap"><h1>ServiceFlow — заявки</h1><p>Останні 100 заявок. Зовнішні інтеграції: '.(defined('SF_WEBHOOK_URL')?'налаштовано endpoint; перевірте доставку':'не налаштовані').'.</p><form method="get"><input type="hidden" name="page" value="serviceflow"><label>Статус <select name="sf_status"><option value="">Усі</option>';foreach(['new','contacted','qualified','won','lost'] as $s)echo '<option '.selected($status,$s,false).'>'.esc_html($s).'</option>';echo '</select></label> <label>Джерело <select name="sf_source"><option value="">Усі</option>';foreach(['quiz','booking','contact','service_form','order'] as $s)echo '<option '.selected($source,$s,false).'>'.esc_html($s).'</option>';echo '</select></label> <button class="button">Фільтрувати</button></form><table class="widefat striped" style="margin:20px 0"><thead><tr><th>Дата / ID</th><th>Контакт</th><th>Послуга</th><th>Статус</th><th>Доставка</th><th>Дії</th></tr></thead><tbody>';foreach($rows as $r){$p=json_decode($r['payload'],true);echo '<tr><td>'.esc_html($r['created_at']).'<br><code>'.esc_html($r['lead_id']).'</code></td><td>'.esc_html($p['name']).'<br>'.esc_html($p['phone']).'</td><td>'.esc_html($r['service']).'<br>'.esc_html($r['source']).'</td><td><form action="'.esc_url(admin_url('admin-post.php')).'" method="post"><input type="hidden" name="action" value="sf_status"><input type="hidden" name="lead_id" value="'.esc_attr($r['lead_id']).'">';wp_nonce_field('sf_status');echo '<select name="status">';foreach(['new','contacted','qualified','won','lost'] as $s)echo '<option '.selected($r['status'],$s,false).'>'.esc_html($s).'</option>';echo '</select><button class="button">Зберегти</button></form></td><td>'.esc_html($r['delivery']).' · '.(int)$r['attempts'].' спроб</td><td><form action="'.esc_url(admin_url('admin-post.php')).'" method="post"><input type="hidden" name="action" value="sf_retry"><input type="hidden" name="lead_id" value="'.esc_attr($r['lead_id']).'">';wp_nonce_field('sf_retry');echo '<button class="button">Повторити доставку</button></form></td></tr>';}echo '</tbody></table>';foreach(['sf_export'=>'Експорт CSV','sf_seed'=>'Створити відсутні демосторінки та пакети'] as $action=>$label){echo '<form action="'.esc_url(admin_url('admin-post.php')).'" method="post" style="margin:15px 0"><input type="hidden" name="action" value="'.esc_attr($action).'">';wp_nonce_field($action);echo '<button class="button button-primary">'.esc_html($label).'</button></form>';}echo '<p>Існуючі сторінки не перезаписуються. Плагін не встановлює Elementor Pro і не вмикає реальні оплати. Підключіть SMTP, n8n та сервіси окремо.</p></div>';}
function sf_admin_guard($action){if(!current_user_can('manage_options'))wp_die('Forbidden',403);check_admin_referer($action);}
add_action('admin_post_sf_status',function(){sf_admin_guard('sf_status');$status=sanitize_key($_POST['status']??'');if(!in_array($status,['new','contacted','qualified','won','lost'],true))wp_die('Invalid status');global $wpdb;$t=sf_tables();$wpdb->update($t['leads'],['status'=>$status],['lead_id'=>sanitize_text_field($_POST['lead_id']??'')]);wp_safe_redirect(admin_url('admin.php?page=serviceflow'));exit;});
add_action('admin_post_sf_retry',function(){sf_admin_guard('sf_retry');global $wpdb;$t=sf_tables();$id=sanitize_text_field($_POST['lead_id']??'');$wpdb->update($t['leads'],['attempts'=>0,'delivery'=>'pending'],['lead_id'=>$id]);sf_deliver($id);wp_safe_redirect(admin_url('admin.php?page=serviceflow'));exit;});
add_action('admin_post_sf_export',function(){sf_admin_guard('sf_export');global $wpdb;$t=sf_tables();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="serviceflow-leads.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['lead_id','created_at','source','service','status','name','phone','email','delivery']);$rows=$wpdb->get_results("SELECT * FROM {$t['leads']} ORDER BY id DESC LIMIT 5000",ARRAY_A);foreach($rows as $r){$d=json_decode($r['payload'],true);$values=[$r['lead_id'],$r['created_at'],$r['source'],$r['service'],$r['status'],$d['name'],$d['phone'],$d['email'],$r['delivery']];$values=array_map(fn($v)=>preg_match('/^[=+@\-\t\r]/',strval($v))?"'".$v:$v,$values);fputcsv($out,$values);}fclose($out);exit;});
add_action('admin_post_sf_seed',function(){sf_admin_guard('sf_seed');$pages=['sf-home'=>['ServiceFlow',''],'sf-services'=>['Послуги','services'],'sf-quiz'=>['Оцінка вартості','quiz'],'sf-packages'=>['Пакети','packages'],'sf-booking'=>['Онлайн-запис','booking'],'sf-about'=>['Про сервіс','about'],'sf-cases'=>['Сценарії','cases'],'sf-blog'=>['Блог','blog'],'sf-contacts'=>['Контакти','contacts'],'sf-privacy'=>['Політика обробки даних','privacy'],'sf-terms'=>['Умови','terms']];foreach($pages as $slug=>$p){if(get_page_by_path($slug))continue;$id=wp_insert_post(['post_type'=>'page','post_status'=>'publish','post_title'=>$p[0],'post_name'=>$slug,'post_content'=>'[serviceflow_app route="'.$p[1].'"]']);if(is_wp_error($id)||!$id)continue;update_post_meta($id,'_wp_page_template','elementor_canvas');update_post_meta($id,'_elementor_edit_mode','builder');update_post_meta($id,'_elementor_version','3.0.0');$data=[['id'=>'sfroot01','elType'=>'container','isInner'=>false,'settings'=>['content_width'=>'full'],'elements'=>[['id'=>'sfapp001','elType'=>'widget','widgetType'=>'shortcode','settings'=>['shortcode'=>'[serviceflow_app route="'.$p[1].'"]'],'elements'=>[]]]]];update_post_meta($id,'_elementor_data',wp_slash(wp_json_encode($data)));}
if(class_exists('WooCommerce')){update_option('woocommerce_currency','UAH');foreach(['cart'=>['Кошик','woocommerce_cart'],'checkout'=>['Оформлення','woocommerce_checkout'],'myaccount'=>['Мій кабінет','woocommerce_my_account']] as $slug=>$v){$page=get_page_by_path('sf-'.$slug);$id=$page?$page->ID:wp_insert_post(['post_type'=>'page','post_status'=>'publish','post_title'=>$v[0],'post_name'=>'sf-'.$slug,'post_content'=>'['.$v[1].']']);if($id)update_option('woocommerce_'.$slug.'_page_id',$id);}foreach(sf_catalog()['packages'] as $p){$sku='sf-'.$p['id'];if(wc_get_product_id_by_sku($sku))continue;$product=new WC_Product_Simple();$product->set_name('ServiceFlow '.$p['name']);$product->set_sku($sku);$product->set_virtual(true);$product->set_regular_price($p['price']);$product->set_description(implode("\n",$p['items'])."\nДемонстраційний пакет. Реального надання послуг немає.");$product->set_status('publish');$product->save();}}
wp_safe_redirect(admin_url('admin.php?page=serviceflow'));exit;});
// Do not emit local-business ratings or fake addresses. All app pages are demonstration-only.
add_action('wp_head',function(){global $post;if($post&&has_shortcode($post->post_content,'serviceflow_app'))echo '<meta name="robots" content="noindex,follow">';});
